logic:
if (element.textContent.trim() !== 'Browse by category') return;
if (element.nextElementSibling && element.nextElementSibling.classList.contains('category-text-list')) return;

var relatedInterests = document.querySelector('[data-test-id="related-interests"]');
if (!relatedInterests) return;

var interestItems = relatedInterests.querySelectorAll('[data-test-id="interestRep"] a');
if (interestItems.length === 0) return;

var ul = document.createElement('ul');
ul.className = 'category-text-list';
ul.style.listStyle = 'none';
ul.style.padding = '0';
ul.style.margin = '16px 0 24px 0';
ul.style.display = 'flex';
ul.style.flexWrap = 'wrap';
ul.style.gap = '8px';
ul.style.maxWidth = '1244px';
ul.style.width = '100%';

for (var i = 0; i < interestItems.length; i++) {
    var link = interestItems[i];
    var href = link.getAttribute('href') || '#';
    var titleEl = link.querySelector('[data-test-id="topic-rep-title"]');
    var text = titleEl ? titleEl.textContent.trim() : link.textContent.trim();
    if (!text) continue;

    var li = document.createElement('li');
    var a = document.createElement('a');
    a.href = href;
    a.textContent = text;
    a.style.display = 'inline-block';
    a.style.padding = '8px 16px';
    a.style.borderRadius = '20px';
    a.style.backgroundColor = '#efefef';
    a.style.color = '#111';
    a.style.textDecoration = 'none';
    a.style.fontSize = '14px';
    a.style.fontWeight = '500';
    a.style.transition = 'background-color 0.2s';
    a.style.cursor = 'pointer';

    li.appendChild(a);
    ul.appendChild(li);
}

var headingContainer = element.parentElement;
if (headingContainer) {
    headingContainer.parentElement.insertBefore(ul, headingContainer.nextSibling);
}
